(()=>{document.addEventListener("DOMContentLoaded",()=>{let r=document.querySelector(".site-header"),c=window.scrollY,s=!0;window.addEventListener("scroll",()=>{let e=window.scrollY;e>c?s||(r.classList.add("hide"),s=!0):(s||e===0)&&(r.classList.remove("hide"),s=!1),c=e});let i=document.getElementById("menu-toggle"),n=document.getElementById("menu-drawer"),l=document.getElementById("menu-close");i.addEventListener("click",function(){n.classList.add("open")}),l.addEventListener("click",function(){n.classList.remove("open")}),document.addEventListener("click",function(e){!n.contains(e.target)&&!i.contains(e.target)&&n.classList.remove("open")});let d=document.querySelectorAll(".bar"),a=new IntersectionObserver(e=>{e.forEach(t=>{if(t.isIntersecting){let o=t.target,g=o.getAttribute("data-years"),h=o.getAttribute("data-colors");o.style.width=`${g*5}%`,o.style.backgroundColor=h}})},{threshold:.5});d.forEach(e=>a.observe(e));let u=document.querySelectorAll(".timeline-item, .highlight-card"),m=new IntersectionObserver(e=>{e.forEach(t=>{t.isIntersecting&&t.target.classList.add("visible")})},{threshold:.2});u.forEach(e=>m.observe(e))});})();
